package com.iotplatform.firmware.service;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Pattern;
import java.security.MessageDigest;

/**
 * Multi-tenant firmware update service for IoT gateway devices.
 * Each tenant's devices are isolated via namespace partitioning.
 */
public class FirmwareUpdateService {

    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z0-9_\\-]{1,64}$");
    private static final Pattern SAFE_VERSION = Pattern.compile("^[0-9]+\\.[0-9]+\\.[0-9]+$");
    private static final String FIRMWARE_BASE = "/opt/iot/firmware";
    private final ConcurrentHashMap<String, TenantContext> tenantRegistry;
    private final AuditLogger auditLogger;

    public FirmwareUpdateService() {
        this.tenantRegistry = new ConcurrentHashMap<>();
        this.auditLogger = new AuditLogger();
    }

    public void registerTenant(String tenantId, String namespace) {
        if (!SAFE_IDENTIFIER.matcher(tenantId).matches()) {
            throw new SecurityException("Invalid tenant ID format");
        }
        if (!SAFE_IDENTIFIER.matcher(namespace).matches()) {
            throw new SecurityException("Invalid namespace format");
        }
        tenantRegistry.put(tenantId, new TenantContext(tenantId, namespace));
    }

    /**
     * Applies a firmware update to a specific device within a tenant's namespace.
     * Uses hardware-level flash tool that requires native process invocation.
     */
    public UpdateResult applyFirmwareUpdate(String tenantId, String deviceId, 
                                            String version, Map<String, String> metadata) {
        // Validate tenant exists and is active
        TenantContext ctx = tenantRegistry.get(tenantId);
        if (ctx == null) {
            return UpdateResult.error("Unknown tenant");
        }

        // Validate device ID format
        if (!SAFE_IDENTIFIER.matcher(deviceId).matches()) {
            return UpdateResult.error("Invalid device ID");
        }

        // Validate version format
        if (!SAFE_VERSION.matcher(version).matches()) {
            return UpdateResult.error("Invalid version format");
        }

        // Construct firmware path with tenant isolation
        String firmwarePath = buildFirmwarePath(ctx.getNamespace(), deviceId, version);

        // Verify firmware file exists and checksum matches
        if (!verifyFirmwareIntegrity(firmwarePath, metadata.get("sha256"))) {
            return UpdateResult.error("Firmware integrity check failed");
        }

        // Build the flash command with tenant-scoped device addressing
        List<String> flashCommand = buildFlashCommand(ctx, deviceId, firmwarePath, metadata);

        auditLogger.log(tenantId, deviceId, "FIRMWARE_UPDATE", version);

        return executeFlashOperation(flashCommand, ctx);
    }

    private String buildFirmwarePath(String namespace, String deviceId, String version) {
        return String.format("%s/%s/%s/firmware-%s.bin", FIRMWARE_BASE, namespace, deviceId, version);
    }

    private boolean verifyFirmwareIntegrity(String path, String expectedHash) {
        try {
            if (expectedHash == null || expectedHash.length() != 64) return false;
            byte[] content = Files.readAllBytes(Paths.get(path));
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] digest = md.digest(content);
            String actual = bytesToHex(digest);
            return actual.equalsIgnoreCase(expectedHash);
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Builds the native flash command as argument list. The device bus address is derived from
     * the tenant context and device registration, not from user input directly.
     */
    private List<String> buildFlashCommand(TenantContext ctx, String deviceId, 
                                           String firmwarePath, Map<String, String> metadata) {
        // Get the hardware bus address from tenant's device registry
        String busAddress = ctx.resolveDeviceBusAddress(deviceId);

        // The flash-tool binary path is fixed
        String toolPath = "/usr/local/bin/iot-flash-tool";

        // Build command as argument list to avoid shell interpretation
        List<String> cmd = new ArrayList<>();
        cmd.add(toolPath);
        cmd.add("--bus");
        cmd.add(busAddress);
        cmd.add("--image");
        cmd.add(firmwarePath);
        cmd.add("--namespace");
        cmd.add(ctx.getNamespace());

        // Apply optional flash parameters from device profile
        String flashMode = resolveFlashMode(metadata);
        cmd.add("--mode");
        cmd.add(flashMode);

        return cmd;
    }

    /**
     * Resolves flash mode from metadata with fallback to default.
     * Validates against known modes.
     */
    private String resolveFlashMode(Map<String, String> metadata) {
        String mode = metadata.getOrDefault("flash_mode", "standard");
        // Normalize the mode identifier
        return normalizeParameter(mode);
    }

    /**
     * Normalizes a parameter value by applying encoding normalization.
     * This handles cases where device profiles contain Unicode identifiers.
     */
    private String normalizeParameter(String input) {
        if (input == null) return "standard";
        // Strip any non-printable characters
        String cleaned = input.replaceAll("[^\\x20-\\x7E]", "");
        // Apply NFKC normalization equivalent for ASCII subset
        // Map common lookalike sequences to canonical form
        cleaned = cleaned.replace("\u2010", "-")  // hyphen
                         .replace("\u2011", "-")  // non-breaking hyphen
                         .replace("\u2012", "-"); // figure dash

        // Validate against allowed modes after normalization
        Set<String> allowedModes = Set.of("standard", "fast", "safe", "recovery");
        if (allowedModes.contains(cleaned)) {
            return cleaned;
        }
        return "standard";
    }

    private UpdateResult executeFlashOperation(List<String> command, TenantContext ctx) {
        try {
            // Execute with explicit argument list - no shell interpretation
            List<String> wrappedCmd = new ArrayList<>();
            wrappedCmd.add("/usr/bin/cgexec");
            wrappedCmd.add("-g");
            wrappedCmd.add("memory,cpu:" + ctx.getCgroupPath());
            wrappedCmd.addAll(command);

            ProcessBuilder pb = new ProcessBuilder(wrappedCmd);
            pb.environment().put("IOT_TENANT", ctx.getTenantId());
            pb.redirectErrorStream(true);

            Process proc = pb.start();
            String output = readProcessOutput(proc);
            int exitCode = proc.waitFor();

            if (exitCode == 0) {
                return UpdateResult.success(output);
            } else {
                return UpdateResult.error("Flash failed: " + output);
            }
        } catch (Exception e) {
            return UpdateResult.error("Execution error: " + e.getMessage());
        }
    }

    private String readProcessOutput(Process proc) throws IOException {
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(proc.getInputStream()))) {
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line).append("\n");
            }
            return sb.toString().trim();
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    // Inner classes
    static class TenantContext {
        private final String tenantId;
        private final String namespace;
        private final Map<String, String> deviceBusMap;

        TenantContext(String tenantId, String namespace) {
            this.tenantId = tenantId;
            this.namespace = namespace;
            this.deviceBusMap = new HashMap<>();
        }

        String getTenantId() { return tenantId; }
        String getNamespace() { return namespace; }
        String getCgroupPath() { return "/iot/" + namespace; }

        String resolveDeviceBusAddress(String deviceId) {
            // In production, this queries the hardware registry
            // Returns validated bus address like "0x1A:03"
            return deviceBusMap.getOrDefault(deviceId, "0x00:00");
        }

        void registerDevice(String deviceId, String busAddress) {
            deviceBusMap.put(deviceId, busAddress);
        }
    }

    static class UpdateResult {
        private final boolean success;
        private final String message;

        private UpdateResult(boolean success, String message) {
            this.success = success;
            this.message = message;
        }

        static UpdateResult success(String msg) { return new UpdateResult(true, msg); }
        static UpdateResult error(String msg) { return new UpdateResult(false, msg); }

        boolean isSuccess() { return success; }
        String getMessage() { return message; }
    }

    static class AuditLogger {
        void log(String tenantId, String deviceId, String action, String detail) {
            System.out.printf("[AUDIT] tenant=%s device=%s action=%s detail=%s%n",
                tenantId, deviceId, action, detail);
        }
    }
}
